1590→    // (Making RuleClasses first-class values will help us to build a
  1591→    // rich query output mode that includes values from loaded .bzl files.)
  1592→    // [Note from brandjon: Even if we merge RuleFunction and RuleClass, it may still be useful to
  1593→    // carry a distinction between loading-time vs analysis-time information about a rule type,
  1594→    // particularly when it comes to the possibility of lazy .bzl loading. For example, you can in
  1595→    // principle evaluate a BUILD file without loading and digesting .bzls that are only used by the
  1596→    // implementation function.]
  1597→    public StarlarkRuleFunction(
  1598→        RuleClass.Builder builder, Location definitionLocation, Symbol<?> identityToken) {
  1599→      this.builder = builder;
  1600→      this.definitionLocation = definitionLocation;
  1601→      this.identityToken = identityToken;
  1602→    }
  1603→
  1604→    @Override
  1605→    public String getName() {
  1606→      return ruleClass != null ? ruleClass.getName() : "unexported rule";
  1607→    }
  1608→
  1609→    @Override
  1610→    public Object call(StarlarkThread thread, Tuple args, Dict<String, Object> kwargs)
  1611→        throws EvalException, InterruptedException {
  1612→      if (!args.isEmpty()) {
  1613→        throw new EvalException("Unexpected positional arguments");
  1614→      }
  1615→      if (ruleClass == null) {
  1616→        throw new EvalException("Invalid rule class hasn't been exported by a bzl file");
  1617→      }
  1618→      Package.Builder pkgBuilder = Package.Builder.fromOrNull(thread);
  1619→      if (pkgBuilder == null) {
  1620→        throw new EvalException(
  1621→            // TODO: #19922 - Clarify message. See analogous TODO for macros, above.
  1622→            "Cannot instantiate a rule when loading a .bzl file. "
  1623→                + "Rules may be instantiated only in a BUILD thread.");
  1624→      }
  1625→
  1626→      validateRulePropagatedAspects(ruleClass);
  1627→
  1628→      ImmutableSet<String> legacyAnyTypeAttrs = getLegacyAnyTypeAttrs(ruleClass);
  1629→
  1630→      try {
  1631→        // Temporarily remove `pkgBuilder` from the thread to prevent calls to load time functions.
  1632→        // Mutating values in initializers is mostly not a problem, because the attribute values are
  1633→        // copied before calling the initializers (<-TODO) and before they are set on the target.
  1634→        // Exception is a legacy case allowing arbitrary type of parameter values. In that case the
  1635→        // values may be mutated by the initializer, but they are still copied when set on the
  1636→        // target.
  1637→        thread.setThreadLocal(StarlarkThreadContext.class, null);
  1638→        // Allow access to the LabelConverter to support native.package_relative_label() in an
  1639→        // initializer.
  1640→        thread.setThreadLocal(LabelConverter.class, pkgBuilder.getLabelConverter());
  1641→        thread.setUncheckedExceptionContext(() -> "an initializer");
  1642→
  1643→        // We call all the initializers of the rule and its ancestor rules, proceeding from child to
  1644→        // ancestor, so each initializer can transform the attributes it knows about in turn.
