  if (pkgBuilder == null) {
    throw new EvalException(
        // TODO: #19922 - Clarify message. See analogous TODO for macros, above.
        "Cannot instantiate a rule when loading a .bzl file. "
            + "Rules may be instantiated only in a BUILD thread.");
  }

